// WF-01 · Normalización al contrato interno de BlinkSec.
//
// Punto de desacople del sistema: a partir de aquí nada sabe de qué
// plataforma vino la alerta. Añadir un tercer SIEM se resuelve escribiendo un
// normalizador en lib/normalize.js, sin tocar nada aguas abajo.

// ─── inyectado desde lib/normalize.js — NO EDITAR AQUÍ ───
// Editar el fichero original y recompilar: npm run build
/**
 * BlinkSec WF-01 — Normalización.
 *
 * Convierte los esquemas heterogéneos de Splunk y Elastic en un único
 * contrato interno. Éste es el punto de desacople del sistema: todo lo que
 * está aguas abajo (enriquecimiento, scoring, contención) opera sobre el
 * esquema normalizado y no sabe de qué plataforma vino la alerta. Añadir un
 * tercer SIEM significa escribir un normalizador aquí y nada más.
 *
 * Wazuh se retiró como fuente de ingesta — ver docs/riesgos.md (R-19).
 *
 * Principio de diseño: los datos entrantes NUNCA son perfectos. Faltan campos,
 * llegan tipos inesperados y las plataformas cambian su formato entre
 * versiones. Este módulo falla de forma ruidosa y explícita, nunca propaga
 * `undefined` hacia una llamada de API que fallará de forma asíncrona e
 * indepurable tres nodos más adelante.
 *
 * @injectable
 */

const BLINKSEC_VERSION = '1.0';

const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
const HASH_RE = { md5: /^[a-f0-9]{32}$/i, sha1: /^[a-f0-9]{40}$/i, sha256: /^[a-f0-9]{64}$/i };
const DOMAIN_RE = /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/i;

class NormalizationError extends Error {
  constructor(message, details) {
    super(message);
    this.name = 'NormalizationError';
    this.details = details;
  }
}

// ---------------------------------------------------------------------------
// Utilidades de saneado
// ---------------------------------------------------------------------------

/** Acceso seguro a rutas anidadas: 'data.srcip' -> valor o undefined. */
function dig(obj, path) {
  return String(path)
    .split('.')
    .reduce((acc, k) => (acc == null ? undefined : acc[k]), obj);
}

/** Primer valor definido y no vacío de una lista de rutas candidatas. */
function firstOf(obj, paths) {
  for (const p of paths) {
    const v = dig(obj, p);
    if (v !== undefined && v !== null && v !== '') return v;
  }
  return undefined;
}

function isPublicIPv4(value) {
  if (typeof value !== 'string' || !IPV4_RE.test(value)) return false;
  const [a, b] = value.split('.').map(Number);
  if (a === 10) return false;                       // RFC1918
  if (a === 172 && b >= 16 && b <= 31) return false; // RFC1918
  if (a === 192 && b === 168) return false;          // RFC1918
  if (a === 127) return false;                       // loopback
  if (a === 169 && b === 254) return false;          // link-local
  if (a === 0 || a >= 224) return false;             // reservado / multicast
  return true;
}

function classifyHash(value) {
  if (typeof value !== 'string') return null;
  const v = value.trim();
  for (const [type, re] of Object.entries(HASH_RE)) {
    if (re.test(v)) return { value: v.toLowerCase(), type };
  }
  return null;
}

/**
 * Saneador de payloads sintácticamente irregulares.
 *
 * Elastic serializa alertas múltiples de formas que NO son JSON válido:
 *   - ndjson:            {...}\n{...}
 *   - coma terminal:     [{...},{...},]
 * Ambos casos revientan JSON.parse. Antes que fallar toda la ingesta por un
 * detalle de serialización aguas arriba, se recuperan aquí; el arreglo real
 * es del lado de Elastic (`.asJSON` / `{{#ParseHjson}}` en la plantilla
 * Mustache), pero el SOAR no puede depender de que alguien lo configure bien.
 */
function parseLoose(raw) {
  if (typeof raw !== 'string') return raw;
  const text = raw.trim();
  if (!text) throw new NormalizationError('Cuerpo vacío');

  try {
    return JSON.parse(text);
  } catch (_) {
    /* se intentan las recuperaciones de abajo */
  }

  // Coma terminal en arrays u objetos: [{},{},]  /  {"a":1,}
  const sinComaFinal = text.replace(/,\s*([\]}])/g, '$1');
  try {
    return JSON.parse(sinComaFinal);
  } catch (_) {
    /* siguiente intento */
  }

  // ndjson: una alerta por línea.
  const lineas = text.split('\n').map((l) => l.trim()).filter(Boolean);
  if (lineas.length > 1) {
    const objetos = [];
    for (const linea of lineas) {
      try {
        objetos.push(JSON.parse(linea.replace(/,\s*([\]}])/g, '$1')));
      } catch (_) {
        // Una línea corrupta no invalida el lote entero; se descarta y se
        // deja constancia en el resultado.
        objetos.push({ __blinksec_parse_error: linea.slice(0, 200) });
      }
    }
    if (objetos.some((o) => !o.__blinksec_parse_error)) return objetos;
  }

  throw new NormalizationError('No se pudo parsear el payload ni como JSON, ni con coma terminal, ni como ndjson', {
    preview: text.slice(0, 300),
  });
}

// ---------------------------------------------------------------------------
// Normalizadores por plataforma
// ---------------------------------------------------------------------------

function normalizeSplunk(a) {
  // La acción de alerta de Splunk envuelve la primera fila del evento en
  // `result`; con Better Webhooks el token $$full_result$$ puede traer más.
  const r = a.result ?? a._result ?? a;
  const ips = [];
  const srcIp = firstOf(r, ['src_ip', 'src', 'clientip']);
  const dstIp = firstOf(r, ['dest_ip', 'dest']);
  if (isPublicIPv4(srcIp)) ips.push({ value: srcIp, direction: 'src' });
  if (isPublicIPv4(dstIp)) ips.push({ value: dstIp, direction: 'dst' });

  const hashes = [];
  for (const p of ['file_hash', 'sha256', 'md5', 'process_hash']) {
    const h = classifyHash(dig(r, p));
    if (h) hashes.push(h);
  }

  return {
    source: 'splunk',
    rule: {
      id: String(firstOf(a, ['sid', 'search_name']) ?? ''),
      name: firstOf(a, ['search_name']) ?? '',
      // Splunk no expone un "level" comparable; se mapea la urgencia de ES
      // si existe, y si no se asume media (8) para no inflar la puntuación.
      level: mapSplunkUrgency(firstOf(r, ['urgency', 'severity'])),
      mitre: toArray(firstOf(r, ['annotations.mitre_attack', 'mitre_technique_id'])),
    },
    asset: {
      host: firstOf(r, ['host', 'dest', 'dest_nt_host']) ?? '',
      ip: isPublicIPv4(dstIp) ? dstIp : (firstOf(r, ['dest_ip']) ?? null),
    },
    identity: { user: firstOf(r, ['user', 'src_user']) ?? null, domain: firstOf(r, ['user_domain']) ?? null },
    artifacts: { ips, hashes, domains: [], urls: [] },
    eventTimestamp: firstOf(r, ['_time']) ?? firstOf(a, ['result._time']) ?? null,
    resultsLink: firstOf(a, ['results_link']) ?? null,
  };
}

function mapSplunkUrgency(u) {
  const m = { informational: 3, low: 5, medium: 8, high: 12, critical: 14 };
  if (typeof u === 'number') return u;
  return m[String(u ?? '').toLowerCase()] ?? 8;
}

function toArray(v) {
  if (v == null) return [];
  return Array.isArray(v) ? v : [v];
}

function normalizeElastic(a) {
  const ctx = a.context ?? a;
  const ips = [];
  const srcIp = firstOf(ctx, ['source.ip', 'src_ip', 'client.ip']);
  const dstIp = firstOf(ctx, ['destination.ip', 'dest_ip', 'server.ip']);
  if (isPublicIPv4(srcIp)) ips.push({ value: srcIp, direction: 'src' });
  if (isPublicIPv4(dstIp)) ips.push({ value: dstIp, direction: 'dst' });

  const hashes = [];
  for (const p of ['file.hash.sha256', 'file.hash.md5', 'file.hash.sha1', 'process.hash.sha256']) {
    const h = classifyHash(dig(ctx, p));
    if (h) hashes.push(h);
  }

  return {
    source: 'elastic',
    rule: {
      id: String(firstOf(ctx, ['rule.id', 'kibana.alert.rule.uuid']) ?? ''),
      name: firstOf(ctx, ['rule.name', 'kibana.alert.rule.name']) ?? '',
      level: mapElasticSeverity(firstOf(ctx, ['rule.severity', 'kibana.alert.severity', 'event.severity'])),
      mitre: toArray(firstOf(ctx, ['rule.threat.technique.id'])),
    },
    asset: {
      host: firstOf(ctx, ['host.name', 'host.hostname', 'agent.name']) ?? '',
      ip: firstOf(ctx, ['host.ip']) ?? null,
    },
    identity: { user: firstOf(ctx, ['user.name']) ?? null, domain: firstOf(ctx, ['user.domain']) ?? null },
    artifacts: { ips, hashes, domains: [], urls: [] },
    eventTimestamp: firstOf(ctx, ['@timestamp', 'event.created']) ?? null,
  };
}

function mapElasticSeverity(s) {
  const m = { low: 5, medium: 8, high: 12, critical: 14 };
  if (typeof s === 'number') return Math.min(15, Math.max(0, s));
  return m[String(s ?? '').toLowerCase()] ?? 8;
}

const NORMALIZERS = { splunk: normalizeSplunk, elastic: normalizeElastic };

// ---------------------------------------------------------------------------
// Entrada pública
// ---------------------------------------------------------------------------

/**
 * Valida el resultado antes de dejarlo pasar aguas abajo.
 *
 * Una alerta sin artefactos no es enriquecible: no tiene ni IP ni hash que
 * consultar. Se deja pasar igualmente (puede ser una alerta legítima de
 * comportamiento, ej. escalada de privilegios local) pero se marca, y WF-03
 * la envía a investigación humana en lugar de intentar puntuarla.
 */
function validate(n) {
  const problemas = [];
  if (!n.asset.host) problemas.push('asset.host ausente');
  if (!n.rule.id) problemas.push('rule.id ausente');
  if (!Number.isFinite(n.rule.level)) problemas.push('rule.level no numérico');

  const totalArtefactos =
    n.artifacts.ips.length + n.artifacts.hashes.length + n.artifacts.domains.length + n.artifacts.urls.length;

  return {
    ok: problemas.length === 0,
    problemas,
    enriquecible: totalArtefactos > 0,
  };
}

/**
 * @param {string} source  'splunk' | 'elastic'
 * @param {object|string} payload  objeto ya parseado, o texto crudo
 * @returns {object[]} una o varias alertas normalizadas
 */
function normalize(source, payload) {
  const fn = NORMALIZERS[source];
  if (!fn) throw new NormalizationError(`No hay normalizador para el origen "${source}"`);

  const parsed = parseLoose(payload);
  const lote = Array.isArray(parsed) ? parsed : [parsed];

  return lote
    .filter((item) => item && !item.__blinksec_parse_error)
    .map((item) => {
      const n = fn(item);
      const v = validate(n);
      return {
        blinksec_version: BLINKSEC_VERSION,
        received_at: new Date().toISOString(),
        ...n,
        // asset.criticality lo rellena WF-01 consultando blinksec.assets;
        // aquí se deja el valor conservador para que, si esa consulta falla,
        // el sistema NO trate un activo desconocido como prescindible.
        asset: { ...n.asset, criticality: 'high' },
        validation: v,
        raw: item,
      };
    });
}


// ─── fin de lib/normalize.js ───
// ─── inyectado desde lib/gateway.js — NO EDITAR AQUÍ ───
// Editar el fichero original y recompilar: npm run build
/**
 * BlinkSec WF-00 — Gateway de ingesta.
 *
 * Se ejecuta en el nodo Code inmediatamente posterior al Webhook, ANTES de
 * cualquier lógica de negocio. Un webhook SOAR sin autenticar no es sólo una
 * fuga: quien conozca la URL puede fabricar alertas y provocar el bloqueo
 * automático de infraestructura legítima — una denegación de servicio
 * auto-infligida con la firma de la propia organización.
 *
 * Este módulo es puro (sin I/O) para poder testearse fuera de n8n. El acceso
 * a Redis vive en el workflow, no aquí.
 *
 * @injectable  — tools/build-workflows.js lo inyecta en el JSON del workflow.
 */

const crypto = require('crypto');

const HEADER_SIGNATURE = 'x-blinksec-signature';
const HEADER_TIMESTAMP = 'x-blinksec-timestamp';
const HEADER_SOURCE = 'x-blinksec-source';

const KNOWN_SOURCES = ['splunk', 'elastic'];

class GatewayRejection extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'GatewayRejection';
    this.code = code; // firma_invalida | timestamp_fuera_de_ventana | origen_desconocido | ...
    this.httpStatus = code === 'origen_desconocido' ? 400 : 401;
  }
}

/**
 * Comparación en tiempo constante.
 *
 * Una comparación con `===` filtra, por el tiempo que tarda en fallar, cuántos
 * bytes iniciales del hash acertó el atacante — suficiente para reconstruir la
 * firma byte a byte. timingSafeEqual exige buffers de igual longitud, así que
 * la comprobación de longitud va primero y de forma explícita.
 */
function safeCompare(a, b) {
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  if (bufA.length !== bufB.length) return false;
  return crypto.timingSafeEqual(bufA, bufB);
}

/**
 * Recalcula el HMAC sobre el cuerpo CRUDO.
 *
 * Éste es el error clásico que rompe toda integración de webhooks firmados:
 * usar el JSON ya parseado por n8n ($json.body). El parseo reordena claves,
 * normaliza espacios en blanco y cambia la representación de los números, de
 * modo que el hash jamás coincide con el que calculó el emisor. n8n expone el
 * cuerpo intacto en $json.rawBody sólo si el Webhook tiene rawBody activado.
 */
function computeSignature(rawBody, secret, timestamp) {
  // Se firma `timestamp.body` (esquema tipo Stripe): incluir el timestamp en
  // el material firmado impide que un atacante reutilice una firma válida con
  // un timestamp nuevo para saltarse la ventana anti-replay.
  const signedPayload = `${timestamp}.${rawBody}`;
  return crypto.createHmac('sha256', secret).update(signedPayload, 'utf8').digest('hex');
}

/**
 * Extrae el cuerpo crudo del item que entrega el nodo Webhook.
 *
 * Con la opción "Raw Body" activada, n8n **no** rellena `$json.rawBody` como
 * sugiere buena parte de la documentación: entrega el cuerpo como adjunto
 * binario en `binary.data.data`, codificado en base64. Verificado contra n8n
 * 1.72.1 — ver tests/gateway/rawbody.test.js con la carga real capturada de
 * una ejecución.
 *
 * La distinción es crítica y silenciosa: leer `$json.body` (el JSON ya
 * parseado) devuelve un objeto que al reserializar pierde el espaciado y
 * reordena claves, de modo que el HMAC NUNCA coincidiría y toda la ingesta
 * respondería 401 sin motivo aparente.
 *
 * Se admiten las dos formas para no depender de la versión de n8n.
 */
function extractRawBody(item) {
  if (!item) return '';

  // Forma 1 — n8n 1.72+: adjunto binario en base64.
  const bin = item.binary?.data;
  if (bin?.data) {
    return Buffer.from(bin.data, 'base64').toString('utf8');
  }

  // Forma 2 — algunas versiones y despliegues exponen rawBody en json.
  const json = item.json ?? item;
  if (typeof json.rawBody === 'string' && json.rawBody) return json.rawBody;
  if (Buffer.isBuffer(json.rawBody)) return json.rawBody.toString('utf8');

  return '';
}

function normalizeHeaders(headers) {
  const out = {};
  for (const [k, v] of Object.entries(headers || {})) {
    out[String(k).toLowerCase()] = Array.isArray(v) ? v[0] : v;
  }
  return out;
}

/**
 * Verifica una petición de ingesta entrante.
 *
 * @param {object}  req
 * @param {object}  req.headers
 * @param {string}  req.rawBody      cuerpo sin parsear, tal cual llegó
 * @param {object}  opts
 * @param {object}  opts.secrets     { splunk, elastic }
 * @param {number}  opts.windowSeconds
 * @param {number}  opts.now         epoch en segundos (inyectable para tests)
 * @returns {{source: string, alertId: string, timestamp: number}}
 * @throws  {GatewayRejection}
 */
function verifyRequest(req, opts) {
  const headers = normalizeHeaders(req.headers);
  const windowSeconds = opts.windowSeconds ?? 300;
  const now = opts.now ?? Math.floor(Date.now() / 1000);

  const source = String(headers[HEADER_SOURCE] || '').toLowerCase();
  if (!KNOWN_SOURCES.includes(source)) {
    throw new GatewayRejection('origen_desconocido', `Cabecera ${HEADER_SOURCE} ausente o no reconocida`);
  }

  const secret = opts.secrets?.[source];
  // Token estático: única opción para emisores que rellenan plantillas pero no
  // ejecutan código (el conector Webhook de Kibana), que por tanto no pueden
  // calcular un HMAC sobre el cuerpo. El HMAC SIEMPRE tiene prioridad: el token
  // estático sólo entra en juego si ese origen no tiene secreto de firma.
  const staticToken = secret ? null : opts.staticTokens?.[source];

  if (!secret && !staticToken) {
    // Configuración incompleta del servidor, no culpa del cliente. Se trata
    // como rechazo igualmente: sin credencial no se puede verificar nada.
    // Un origen sin secreto NI token queda deshabilitado, que es el
    // comportamiento seguro: rechazar, no aceptar cualquier cosa.
    throw new GatewayRejection('secreto_no_configurado', `No hay secreto HMAC ni token estático configurado para el origen "${source}"`);
  }

  const rawTimestamp = headers[HEADER_TIMESTAMP];
  if (!rawTimestamp) {
    throw new GatewayRejection('timestamp_ausente', `Falta la cabecera ${HEADER_TIMESTAMP}`);
  }
  const timestamp = Number(rawTimestamp);
  if (!Number.isFinite(timestamp)) {
    throw new GatewayRejection('timestamp_malformado', 'El timestamp no es numérico');
  }

  // Ventana bidireccional: un timestamp en el futuro es tan sospechoso como
  // uno viejo (reloj desincronizado o intento de alargar la validez).
  if (Math.abs(now - timestamp) > windowSeconds) {
    throw new GatewayRejection(
      'timestamp_fuera_de_ventana',
      `Desfase de ${Math.abs(now - timestamp)}s excede la ventana de ${windowSeconds}s`,
    );
  }

  const provided = headers[HEADER_SIGNATURE];
  if (!provided) {
    throw new GatewayRejection('firma_ausente', `Falta la cabecera ${HEADER_SIGNATURE}`);
  }

  const rawBody = typeof req.rawBody === 'string' ? req.rawBody : '';
  if (!rawBody) {
    // Sin cuerpo crudo no hay nada que firmar y n8n probablemente tiene
    // rawBody desactivado en el nodo Webhook. Fallar ruidosamente.
    throw new GatewayRejection('rawbody_ausente', 'rawBody vacío: ¿está activada la opción "Raw Body" en el nodo Webhook?');
  }

  // --- Vía de token estático (postura inferior, deliberada) ----------------
  // No cubre el cuerpo ni el timestamp: no protege contra manipulación del
  // payload en tránsito ni contra reenvío dentro de la ventana. Sólo impide el
  // POST anónimo. Se compensa con SIEM_ALLOWLIST estricta. Ver R-01.
  if (staticToken) {
    if (!safeCompare(provided, String(staticToken))) {
      throw new GatewayRejection('firma_invalida', 'El token estático no coincide');
    }
    return { source, timestamp, rawBody, firmado: false };
  }

  const expected = computeSignature(rawBody, secret, rawTimestamp);
  // Se admite el prefijo "sha256=" que usan varios emisores.
  const cleaned = provided.startsWith('sha256=') ? provided.slice(7) : provided;

  if (!safeCompare(cleaned, expected)) {
    throw new GatewayRejection('firma_invalida', 'La firma HMAC no coincide');
  }

  return { source, timestamp, rawBody, firmado: true };
}

// ---------------------------------------------------------------------------
// Token de reanudación del Human-in-the-Loop (WF-05)
// ---------------------------------------------------------------------------

/**
 * Token que autoriza reanudar una ejecución pausada en espera de aprobación.
 *
 * SIN esto, la URL de reanudación de n8n es adivinable: su forma es
 * `/webhook-waiting/<executionId>/<suffix>`, donde `executionId` es un entero
 * SECUENCIAL de la base de datos y `suffix` una constante. Cualquiera que
 * alcance el endpoint puede recorrer ids y aprobar contenciones ajenas — lo
 * que anula por completo el Human-in-the-Loop, que es el control central del
 * sistema. El endpoint tampoco distingue: responde 404 para un id inexistente,
 * de modo que sirve además para enumerar qué ejecuciones existen.
 *
 * El token se liga a la ejecución Y a la alerta: no vale reutilizar el de otra
 * alerta ni el de otra ejecución. Se trunca a 32 hex (128 bits) — de sobra
 * contra fuerza bruta y mantiene la URL manejable en un botón de Slack.
 */
function computeResumeToken(executionId, alertId, secret) {
  return crypto
    .createHmac('sha256', String(secret))
    .update(`${executionId}.${alertId}`, 'utf8')
    .digest('hex')
    .slice(0, 32);
}

/**
 * Verifica el token de reanudación en tiempo constante.
 *
 * Devuelve false ante cualquier duda (token ausente, secreto sin configurar,
 * longitud distinta). Quien llama DEBE tratar el false como rechazo, nunca
 * como "seguir adelante sin comprobar".
 */
function verifyResumeToken(token, executionId, alertId, secret) {
  if (!token || !secret) return false;
  return safeCompare(String(token), computeResumeToken(executionId, alertId, secret));
}

/**
 * Sanea el nombre que el aprobador declara de sí mismo en la URL.
 *
 * Es un dato AUTODECLARADO, no verificado: quien tiene el token puede escribir
 * cualquier nombre. Se acota para que no contamine el registro de auditoría ni
 * el mensaje de Slack (saltos de línea, marcado, longitud), pero el que quede
 * en `containment_log.approved_by` sigue siendo "quien dijo ser", no "quien
 * fue". Cerrarlo de verdad exige verificar la firma de Slack.
 */
function sanitizeApprover(nombre) {
  if (typeof nombre !== 'string') return null;
  const limpio = nombre.replace(/[^\w.@ -]/g, '').trim().slice(0, 64);
  return limpio || null;
}

/**
 * Identificador determinista de la alerta.
 *
 * Determinista y no aleatorio a propósito: es la clave de idempotencia. Si el
 * SIEM reenvía la misma alerta (reintento por timeout, doble configuración de
 * integración), debe producir exactamente el mismo alert_id para que WF-00 la
 * descarte en vez de abrir un segundo ticket y ejecutar la contención dos veces.
 *
 * Se incluye el timestamp del EVENTO, no el de recepción: dos ataques idénticos
 * en momentos distintos son incidentes distintos.
 */
function deriveAlertId(source, parts) {
  const material = [
    source,
    parts.ruleId ?? '',
    parts.eventTimestamp ?? '',
    parts.host ?? '',
    parts.srcIp ?? '',
  ].join('|');
  return crypto.createHash('sha256').update(material, 'utf8').digest('hex').slice(0, 32);
}


// ─── fin de lib/gateway.js ───

const entrada = $input.first().json;

let alertas;
try {
  alertas = normalize(entrada.source, entrada.rawBody);
} catch (e) {
  // Un payload irrecuperable no se procesa a medias: se deriva a WF-99 con el
  // contexto suficiente para que alguien arregle la regla de origen.
  throw new Error(`Normalización fallida (${entrada.source}): ${e.message}`);
}

// Elastic puede traer varias alertas en un solo POST. Cada una deriva su
// alert_id de SU PROPIO CONTENIDO, no de la posición en el lote.
//
// Antes se usaba `${entrada.alertId}-${i}`, donde el id base salía sólo de la
// PRIMERA alerta del lote. Eso rompía la idempotencia: la misma alerta recibía
// ids distintos según su posición, así que un lote reenviado con una alerta
// menos duplicaba el ticket y volvía a ejecutar la contención. Derivar del
// contenido hace el id estable con independencia del lote en que viaje.
return alertas.map((a) => ({
  json: {
    ...a,
    alert_id: alertas.length === 1
      ? entrada.alertId
      : deriveAlertId(a.source, {
          ruleId: a.rule?.id,
          eventTimestamp: a.eventTimestamp,
          host: a.asset?.host,
          srcIp: (a.artifacts?.ips ?? []).find((i) => i.direction === 'src')?.value,
        }),
    agent_id: entrada.agentId,
    ingestStartedAt: entrada.ingestStartedAt,
  },
}));

// WF-01 · Fusión de la criticidad del activo desde el inventario.
//
// El inventario es lo que distingue aislar un portátil de aislar la base de
// datos de producción. Sin él, todo activo se trata como 'high' y toda
// contención pasa por aprobación humana.
//
// Este nodo procesa TODAS las alertas del lote, no sólo la primera.
//
// Antes hacía `$('Normalizar').first()` y devolvía UN solo item: con un lote
// de Elastic de N alertas, las N-1 restantes se descartaban en silencio y la
// ejecución se reportaba como exitosa. En un SOAR eso son incidentes que nadie
// llega a ver. Verificado con un lote real de 2 alertas: sólo se guardaba la
// primera.
//
// El emparejamiento alerta↔activo se hace por HOSTNAME, no por posición: el
// nodo Postgres se ejecuta una vez por item y no garantiza que el orden de sus
// filas coincida con el de las alertas.

const alertas = $('Normalizar').all().map((i) => i.json);

const porHost = new Map();
for (const item of $input.all()) {
  const fila = item.json;
  if (fila && fila.hostname) porHost.set(String(fila.hostname), fila);
}

return alertas.map((alerta) => {
  const activo = porHost.get(String(alerta.asset?.host));

  if (!activo) {
    // Activo desconocido: se mantiene el 'high' conservador y se deja
    // constancia. Un inventario incompleto es un hallazgo operativo, no una
    // excusa para automatizar a ciegas.
    return {
      json: {
        ...alerta,
        asset: { ...alerta.asset, criticality: 'high', never_isolate: false, inventoryHit: false },
      },
    };
  }

  return {
    json: {
      ...alerta,
      asset: {
        ...alerta.asset,
        criticality: activo.criticality,
        never_isolate: activo.never_isolate === true,
        owner_team: activo.owner_team ?? null,
        inventoryHit: true,
      },
    },
  };
});

// WF-01 · Restauración del payload tras el UPSERT.
//
// El nodo Postgres SUSTITUYE cada item por el resultado de su consulta. Sin
// restaurar, aguas abajo llegaría la fila insertada en vez de la alerta.
//
// Se restauran TODAS las alertas del lote, no sólo la primera: con .first()
// un lote de N alertas se reducía a 1 en este punto.

return $('Fusionar criticidad').all().map((i) => ({ json: i.json }));
